import{_ as t}from"./chunks/editor-zeichnung.C5iY_LPV.js";import{_ as a,o as i,c as n,a3 as o}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"HA Grafik Visual Studio","description":"A different kind of Home Assistant dashboard, with its current development status and editor guide.","frontmatter":{"title":"HA Grafik Visual Studio","description":"A different kind of Home Assistant dashboard, with its current development status and editor guide."},"headers":[],"relativePath":"en/projects/grafik-visual-studio/index.md","filePath":"en/projects/grafik-visual-studio/index.md","lastUpdated":1793006827000}'),s={name:"en/projects/grafik-visual-studio/index.md"};function r(d,e,l,c,g,h){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="ha-grafik-visual-studio" tabindex="-1">HA Grafik Visual Studio <a class="header-anchor" href="#ha-grafik-visual-studio" aria-label="Permalink to &quot;HA Grafik Visual Studio&quot;">​</a></h1><p><strong>Studio 0.1.296:</strong> The remaining <strong>62 widget types</strong> gain DE/EN/FR properties and runtime messages, optional Climate controls and source/attribute/unit checks. Existing projects and package versions remain valid; new groups start disabled. <a href="./ha-quellen-climate">Guide and limits</a>. Mocked tests do not verify real devices/Companion. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/remaining-widget-audit-2026-10-12.md" target="_blank" rel="noreferrer">Audit report</a>.</p><p>Since <strong>0.1.289</strong>, <strong>Save</strong> changes colour during saving: <strong>amber</strong> while the request is pending, <strong>green</strong> after success and <strong>red</strong> on failure. The original colour returns after 1.4 seconds. This also applies to autosave in both light and dark appearance.</p><p>From <strong>Studio 0.1.287</strong>, <strong>every widget</strong> has an <strong>In Runtime verstecken</strong> (Hide in runtime) checkbox at the top of its <strong>WIDGET</strong> tab. It hides the widget in runtime independently of z-index while retaining editor visibility. Calculations and data flow remain active, including hidden Number widgets and Math boxes. Save the project after changing it.</p><p>Other changes through <strong>Studio 0.1.285</strong>: <a href="./svg-line">SVG lines</a> and Value connections support vertical starting positions, vertical-first orthogonal routes and less sensitive point dragging. <a href="./industrial">Rotary outputs</a> directly control line animation. The <a href="./svg-linebox-math">Number-to-Math example</a> explains battery net flow using <code>O - P</code>; the <a href="./bildergalerie">gallery</a> shows the editor setup before the animated demo.</p><p>New in Studio <strong>0.1.280</strong>: <a href="./solar">Solar 0.1.3</a> offers seven bottom line ports on the standalone inverter. Also includes four PV inputs on the stack head, battery ports at the enclosure seam, separate battery reading colors and a mirrored solar panel with base.</p><p>New in Studio <strong>0.1.215</strong>: The external <a href="./materialdesign">Material Design 1.0.0 package</a> contains <strong>49 widget entries</strong>, including autocomplete, inputs, buttons, displays, lists, charts, calendar and page layouts. A comparison project prepares the widget-by-widget review.</p><p>New in Studio <strong>0.1.214</strong>: Material Design package <strong>0.3.0</strong> adds <a href="./materialdesign">Dialog iFrame</a> as the third widget, with source, sandbox, scrolling and compact/advanced dialog layout options.</p><p>New in Studio <strong>0.1.210</strong>: the external <a href="./materialdesign">Material Design set</a> starts with <strong>Preview Color Schemes</strong>, 26 palette rows and Classic/Material 3/Project default. Package 0.1.0 is prepared for testing community catalog registration.</p><h2 id="package-catalog-and-downloads" tabindex="-1">Package catalog and downloads <a class="header-anchor" href="#package-catalog-and-downloads" aria-label="Permalink to &quot;Package catalog and downloads&quot;">​</a></h2><p>The <strong>Weather and Heating 1.7.1</strong> package uses the original preview images from <a href="https://github.com/rg-engineering/ioBroker.vis-2-widgets-weather-and-heating" target="_blank" rel="noreferrer">ioBroker weather-and-heating</a> for seven widgets. “Inform my landlord” uses an envelope icon because the image referenced upstream is missing. The original images&#39; MIT license is included. The update only changes widget images and preserves existing settings. Updating the images requires Studio <strong>0.1.216</strong> or newer.</p><p>Starting with catalog website <strong>0.1.11</strong>, the original package uploaded during registration is stored privately for admin review. Analysis and approval reuse this file without another upload; a replacement file can optionally be uploaded. Administration can download the original. SHA-256 detects changes. The private copy is removed after approval, rejection, deletion or the 90-day retention period. Older submissions require one new upload because previous versions only analyzed the file.</p><p>Starting with catalog website <strong>0.1.10</strong>, widget registration only accepts <code>.wg</code> and tool registration only accepts <code>.tp</code>. The file picker filters by the appropriate extension. The server checks upload filenames and download URL paths, while continuing to validate package contents and manifest type. Upload validation also applies in Administration.</p><p>Catalog website <strong>0.1.9</strong> asks whether a package needs new Studio features (Yes/No/Unsure); Yes or Unsure requires a description and allows the minimum version to be marked “Not yet known”. No requires a specific minimum version. Administration determines the minimum version during review and after any required Studio changes; a specific version must be entered before approval. An optional package upload identifies its renderers/actions; without a file, analysis occurs in Administration. Unknown features receive “Studio update required” and remain outside the public catalog until implemented and reviewed again. The operator must upload the website update.</p><p>Starting with Studio <strong>0.1.212</strong>, a red <code>mdi:alert</code> icon marks the GitHub source and installation notice for widget and tool packages. Installation requires accepting the installation risk.</p><p>Starting with Studio <strong>0.1.213</strong>, available package updates have a green card border. New compatible packages highlight only the <strong>Install</strong> button in blue. The highlight disappears after successful installation or update.</p><p>Studio detects newer approved package versions when opening package settings or choosing <strong>Refresh catalog</strong>, then offers <strong>Update</strong>. Package IDs must match, including packages previously installed locally or from GitHub. Updates are installed deliberately. Arbitrary GitHub repositories are not monitored automatically.</p><p>Widget packages, tool packages and helper tools are provided centrally in the <a href="https://visualstudio.ugso-software.de/?lang=en" target="_blank" rel="noreferrer">UGSo package catalog at visualstudio.ugso-software.de</a>. These include Technic, Weather/Heating, the Colorpicker, and <strong>Widget Test</strong> and <strong>Tools Test</strong> for checking package installation. The <strong>Packer for Windows and Linux</strong> is listed under <strong>Helper tools</strong>. Descriptions and instructions remain on this open-source site; package files are provided through the catalog subdomain.</p><p><strong>A different kind of Home Assistant dashboard.</strong> Grafik Visual Studio is an experimental Home Assistant app with a freeform editing surface and a separate runtime. It is still in early development; its project format and controls may change. It is not yet intended for production dashboards.</p><p><a href="./editor">Editor and keyboard shortcuts</a> · <a href="./widgets">All 74 widgets</a> · <a href="./svg-line">SVG-Line</a> · <a href="./svg-linebox">SVG LineBox with videos</a> · <a href="./svg-linebox-math">SVG LineBox Math</a> · <a href="./widget-packages">Widget package interface</a> · <a href="./tool-packages">Tool package interface</a> · <a href="./packer">Package packer</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio" target="_blank" rel="noreferrer">Source and Home Assistant app</a></p><p><img src="'+t+'" alt="HA Grafik Visual Studio editor with widget palette and SVG connection lines"></p><p><em>Editor view with drawn connection lines. <a href="/images/grafik-visual-studio/editor-zeichnung.png">Open the full-resolution image</a>.</em></p><h2 id="what-works-today" tabindex="-1">What works today <a class="header-anchor" href="#what-works-today" aria-label="Permalink to &quot;What works today&quot;">​</a></h2><p>Starting with Studio <strong>0.1.222</strong>, the light theme uses a gray editor canvas with anthracite grid lines. The dark theme keeps the existing background with slightly brighter grid lines for easier orientation. This appearance applies to the editor. Runtime continues to use the saved page background.</p><p>Starting with Studio <strong>0.1.221</strong>, the interface automatically follows the light/dark preference reported by the browser. The toolbar, sidebars, dialogs and fields also update while Studio is open, without reloading. Saved page backgrounds and widget colors are preserved; changing the theme does not modify saved project settings.</p><p>Starting with Studio <strong>0.1.220</strong>, new pages open the <strong>VIEW</strong> tab directly. It contains general CSS, background, font and text, options, navigation, app bar and responsive settings. Sections can expand and collapse but have no activation checkboxes: page values are preserved on save. Checkboxes for individual options such as “Default” remain available.</p><p>Starting with Studio <strong>0.1.218</strong>, failed HA switch commands show a red runtime alert with the entity ID and error reason. Since <strong>0.1.219</strong>, clicking a blocked Switch also explains the reason, such as a missing or unavailable HA state. Switch widgets control Home Assistant in runtime; editor interaction is a preview.</p><p>Starting with Studio <strong>0.1.217</strong>, the entity dialog searches friendly names, custom and original entity names, entity IDs and device names. Multiple search words can match across entity and device metadata: <strong>Licht Tv1</strong>, for example, finds an entity named “Licht” on device “TV1”. Search is case-insensitive; matching device groups automatically expand while searching.</p><ul><li>Manage multiple projects and named pages, each with its own size, background and widgets. The runtime presents visible pages separately.</li><li>Place, move, resize and name widgets on a scrollable canvas, and arrange them with z-index. The editor supports multiple selection, alignment, size matching, copy/paste and undo/redo.</li><li>Use 74 widgets from “HA Grafik – Basis”, “HA Grafik – Interaktiv”, “HA Grafik – Spezial”, “HA Grafik – Datenfluss” and “HA Grafik – Gauges”. These include HTML, images, numbers, controls, tables, calendars, dashboard embedding, SVG lines, calculations, converters and ten measuring instruments. The palette shows a preview or icon appropriate to each type.</li><li>Edit layout, CSS, “Generell”, visibility and docking-point properties. The editor widget filter uses the “Filterwort” property in “Generell”.</li><li>Draw connection lines with intermediate points, explicitly enabled collector points, colors, arrowheads and animations. Lines that cross do not connect automatically.</li><li>Select files from Home Assistant&#39;s <code>/config/www/studio</code> folder and upload supported files. The file browser automatically creates this root folder when opened. If write permissions are missing, it displays instructions for creating the folder manually. Widget image selection uses the same folder; applied and copied paths start with <code>/local/studio/</code>. The entity browser can search entities and current states and insert entity IDs into widget fields.</li><li>The Files search field searches filenames and paths across all <code>/config/www/studio</code> subfolders, independently of the open folder and without case sensitivity. Results show image previews and relative paths; file-type filters and image insertion remain available. Clearing the search restores the open folder listing.</li><li>Individual and all-widget checkboxes immediately update the editor selection. The selection list stays in front of all widgets. From <strong>0.1.209</strong>, use the toolbar&#39;s <strong>Copy</strong> and <strong>Delete</strong> actions for checked widgets; duplicate buttons at the bottom of the list have been removed. Deletion uses the confirmation dialog. Signal images, extra controls and docking points are disabled for new widgets and can be enabled when needed.</li><li>Drag any selected widget to move the entire selection together, including after copying and pasting. Selected SVG lines and intermediate points move with the selection while existing attachments remain intact. Locked widgets block the shared move. Each drag can be undone as one operation.</li><li>Deleting widgets opens a confirmation dialog listing their IDs. Cancel or Escape aborts deletion. “Suppress this question for the next 5 minutes” skips subsequent deletion prompts for five minutes in the open editor. Deletion remains undoable.</li><li>Save changes automatically after a configurable delay (five seconds by default) or save manually. Widgets can be exported and imported as JSON.</li><li>The interface follows Home Assistant&#39;s language: German when HA is set to German, English otherwise. Under <strong>Settings → Language</strong>, each browser can choose <strong>Automatic</strong>, <strong>German</strong> or <strong>English</strong>. Project and widget content is left unchanged.</li></ul><h2 id="updates-through-0-1-158" tabindex="-1">Updates through 0.1.158 <a class="header-anchor" href="#updates-through-0-1-158" aria-label="Permalink to &quot;Updates through 0.1.158&quot;">​</a></h2><p>The <a href="./widgets">widget reference</a> now explains the VIS2-inspired value lists, Bool HTML/Checkbox/Select, Table, HTML State, Bar, HTML/navigation, filters, String and Input val, with screenshots. CSS General stays enabled for every widget. Migration hints can be switched off under Settings → General.</p><p><strong>Dashboard in widget</strong> under Special embeds an HA dashboard up to 800 × 640 pixels. <strong>View in widget</strong> continues to embed Studio pages. <a href="./datenfluss">Data flow</a> provides Value connection, Value converter and Value calculation; <a href="./svg-linebox-math">LineBox Math</a> supports four calculations and configurable presentation.</p><h2 id="planned-extensions" tabindex="-1">Planned extensions <a class="header-anchor" href="#planned-extensions" aria-label="Permalink to &quot;Planned extensions&quot;">​</a></h2><p>Grafik Visual Studio is intended to support creating, distributing and independently displaying visualizations. The following items are development goals. They do not describe fully available features yet; their scope and order may change based on testing and feedback. The current feature set is listed under <strong>What works today</strong>.</p><ul><li><strong>Complete project export and import:</strong> Back up and transfer projects, including required images, settings and package information, and restore them on another installation. The planned project package export extends the existing JSON export of individual widgets.</li><li><strong>Standalone runtime on a separate device:</strong> Run finished visualizations independently of the editor, for example on a Raspberry Pi used as a wall display or control panel. The Home Assistant connection should be configurable. The existing runtime view provides the foundation; a standalone runtime package for separate devices is a further goal.</li><li><strong>Companion app for connecting installations:</strong> An additional application should simplify setup and connections between Studio, the runtime and Home Assistant. Its exact scope is still to be defined.</li><li><strong>Extended Packer with GitHub features:</strong> Create widget and tool packages locally, with optional creation of a GitHub repository and publishing of package versions. Local packaging should remain available without GitHub. See <a href="./packer">Package packer</a> for information about the existing tool.</li><li><strong>Direct package registration from the Packer:</strong> Submit packages to the <a href="https://visualstudio.ugso-software.de/?lang=en" target="_blank" rel="noreferrer">community catalog</a>, using the same registration process and information about licenses, authors, privacy and Studio compatibility as the website. Public catalog entries will still require review.</li></ul><h3 id="information-to-document-alongside-these-features" tabindex="-1">Information to document alongside these features <a class="header-anchor" href="#information-to-document-alongside-these-features" aria-label="Permalink to &quot;Information to document alongside these features&quot;">​</a></h3><ul><li><strong>Portability:</strong> Which resources an export includes, which extension packages are required on the destination, and which connections need to be configured there again.</li><li><strong>Credentials:</strong> How Home Assistant tokens and GitHub credentials are handled. Normal project exports should not contain unencrypted secrets.</li><li><strong>Runtime requirements:</strong> Supported devices, setup, network connections and behavior when a connection is lost.</li><li><strong>Package maintenance and compatibility:</strong> Versioning, updates and compatibility between Studio, the runtime and extension packages.</li><li><strong>Getting involved:</strong> Opportunities for testers and developers, plus ways to report problems and suggest improvements. Problems can be reported through <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/issues" target="_blank" rel="noreferrer">GitHub Issues</a>. Readers arriving from a forum post can also contact the author through that forum&#39;s chat feature; experience with ioBroker VIS/VIS2 is welcome.</li></ul><h2 id="planned-calendar-json-integration" tabindex="-1">Planned: Calendar JSON integration <a class="header-anchor" href="#planned-calendar-json-integration" aria-label="Permalink to &quot;Planned: Calendar JSON integration&quot;">​</a></h2><p>A dedicated Home Assistant integration is planned to expose HA calendars as JSON event lists for calendar widgets and other consumers. The sensor state will contain the event count; the full list will be stored in the <code>events</code> attribute. Date range and refresh interval should be configurable. Event Calendar already supports <code>calendar.*</code> directly; the reusable integration has not been implemented yet.</p><h2 id="current-limitations" tabindex="-1">Current limitations <a class="header-anchor" href="#current-limitations" aria-label="Permalink to &quot;Current limitations&quot;">​</a></h2><p>In the runtime, Sensor, String, Red Number, Bar, Gauge and Bool HTML read a bound Home Assistant entity every five seconds; visibility rules use those states too. A Switch widget can control <code>switch</code>, <code>light</code> and <code>input_boolean</code> through HA service actions and then displays the confirmed HA state. Other data and control widgets still use local sample values. Selecting an entity ID there does not yet provide live binding. Visibility&#39;s “Nur für Gruppen” option and <code>multi-views</code> behavior are not fully implemented. The editor filter affects only the editor view.</p><p>The app provides one standard Home Assistant Ingress entry. Separate sidebar entries for editor and runtime require the additional experimental integration from <code>custom_components/ha_grafik_visual_studio</code>, which requires Home Assistant OS or Supervised with Supervisor. The <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/README.md" target="_blank" rel="noreferrer">repository README</a> explains the installation.</p><p>The interface draws inspiration from VIS2. Grafik Visual Studio is an independent implementation; it does not ship VIS2 code or widgets.</p>',43)])])}const f=a(s,[["render",r]]);export{m as __pageData,f as default};
